/* proxy.c: when this DLL is pdh.dll next to bb-probe.exe (the one-file install), its exports forward to the
 * real pdh.dll from System32 (proxy_pdh.asm jumps through px_ptrs, generated by gen_proxy.py). The exe
 * imports pdh.dll statically and Windows looks in the exe's folder first, so we load before the game's
 * first instruction, like launch.py's early mode, without a debugger. */
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <stdint.h>
#include "proxy_pdh.h"

extern uint64_t px_ptrs[PX_COUNT];
static long __stdcall px_missing(void) { return (long)0xC0000BC6; /* PDH_NOT_IMPLEMENTED */ }

int proxy_init(void) {
    wchar_t p[MAX_PATH];
    UINT n = GetSystemDirectoryW(p, MAX_PATH);
    if (!n || n > MAX_PATH - 10) return 0;
    wcscat_s(p, MAX_PATH, L"\\pdh.dll");
    HMODULE m = LoadLibraryW(p);
    int ok = 0;
    for (int i = 0; i < PX_COUNT; ++i) {
        FARPROC f = m ? GetProcAddress(m, k_px_names[i]) : NULL;
        px_ptrs[i] = f ? (uint64_t)f : (uint64_t)px_missing;
        ok += f != NULL;
    }
    return ok;
}
